Definition sm2_post (ra sp gp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (FSB h : Z) (fl : list Z) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (j : nat) (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem) junk1 junk2,
    ms' = MS (mkR ra sp gp (Z_to_bv 64 tpA) t0' t1' t2' s0 s1 (Z_to_bv 64 (frame_addr FSB 2 ((h + Z.of_nat j) mod 4096)))
                  a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (sm_W 2 FSB ((h + Z.of_nat j) mod 4096) (bv_unsigned sp)) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ (j < 4096)%nat /\ nth (Z.to_nat ((h + Z.of_nat j) mod 4096)) fl 1 = 0
    /\ fs_hint FSB 2 m' (h + Z.of_nat j + 1) /\ fs_const FSB m'
    /\ fs_flags FSB 2 m' (upd fl (Z.to_nat ((h + Z.of_nat j) mod 4096)) 1)
    /\ rw_cells asegs m' (frame_addr FSB 2 ((h + Z.of_nat j) mod 4096))
         [CB 24 junk1; C8 sp; CB 216 junk2; C8 (Z_to_bv 64 (fl_base FSB 2 + (h + Z.of_nat j) mod 4096))]
    /\ rw_cells asegs m' (shad (frame_addr FSB 2 ((h + Z.of_nat j) mod 4096)))
         [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)]
    /\ fs_free_frames FSB 2 m' (upd fl (Z.to_nat ((h + Z.of_nat j) mod 4096)) 1).

Definition sm2_entry : Z := 0xac710.

Lemma stack_malloc_2_spec : forall ra sp gp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (FSB h : Z) (fl : list Z) (DTV dtvbeg TCX T lo : Z) (tb te : word),
  fs_const FSB m -> fs_hint FSB 2 m h -> fs_flags FSB 2 m fl -> flags_ok 2 fl -> (nbusy fl < 4096)%nat -> 0 <= h < 2 ^ 61 ->
  fs_free_frames FSB 2 m fl -> rw_cells asegs m tpA [C8 (Z_to_bv 64 FSB)] ->
  tga_cells DTV dtvbeg m -> thread_cells TCX T m -> ttls_cells T m tb te -> m2s_cells m ->
  FSB_ok2 FSB -> 0x10007fff8000 <= lo -> FSB + kFakeStackSize <= lo ->
  0 < DTV -> DTV + 4096 <= lo -> 0 < dtvbeg < 2 ^ 64 -> 0 < TCX -> TCX + 0xa0 <= lo -> 0 < T -> T + 4096 <= lo ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - 208 -> bv_unsigned sp <= 2 ^ 47 ->
  mem_inv asegs m ->
  evt asegs (sm2_post ra sp gp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc FSB h fl lo m)
    (MS (mkR ra sp gp (Z_to_bv 64 tpA) t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 sm2_entry) fc None m (seg_rom asegs)).
